def sort_values(values):
    if len(values) <= 1:
        return values[:]
    pivot = values[len(values)//2]
    left = [v for v in values if v < pivot]
    equal = [v for v in values if v == pivot]
    right = [v for v in values if v > pivot]
    return sort_values(left) + equal + sort_values(right)
